const seedrandom = require('seedrandom');

//Menuplans generated by https://app.json-generator.com/
const menuPlans = require('./initial_menuplans');
const signups = require('./initial_signups');
const { dataDate } = require('./test-data-config');
const { dateToStandardString } = require('../utils/dateFunctions');
const DAYS = ["Montag", "Dienstag", "Mittwoch", "Donnerstag", "Freitag"];

const menuPlansStatistics = JSON.parse(JSON.stringify(menuPlans));

for(let menuplan of menuPlansStatistics) {
    for(let day in menuplan.days) {
        let date = new Date(menuplan.startDate);
        date.setDate(date.getDate()+DAYS.indexOf(day));
        if(date < new Date(dataDate)){
          date = dateToStandardString(date);
          for(let dish of menuplan.days[day]){
            let registered = signups.filter(signup => signup.day == date && signup.dish.name == dish.name).length;
            let ordered = Math.floor(registered*(1+Math.random()*0.3)*(1+seedrandom(dish.name+"x")()*0.5));
            let served = Math.floor(registered+Math.random()*(ordered-registered));
            let wasted = Math.floor(Math.random()*(ordered-served));
            dish.statistics = {
              ordered: ordered,
              served: served,
              wasted: wasted
            };
          }
        }
    }
}
module.exports = menuPlansStatistics;